import { Swatch } from "march/ui"
import { ContextMenu } from "march/components/context-menu"

// renk paleti: bir renge sağ tıkla; menü o rengin adını ve hex kodunu bilir
const colors = [["Mercan", "#ff6b5b"], ["Nane", "#3ecf8e"], ["Gece", "#2b3a67"], ["Hardal", "#f2b33d"]]

export function ColorSwatches() {
  let $bg = "transparent"
  let $note = "Bir renge sağ tıklayın."
  const items = (target: Element) => {
    const hex = target.closest("[data-hex]")?.getAttribute("data-hex") ?? "#000000"
    return [
      { label: `Arka plan yap (${hex})`, onSelect: () => { $bg = hex; $note = `Arka plan: ${hex}` } },
      { label: "Hex kodunu kopyala", shortcut: "mod+c", onSelect: () => { $note = `Kopyalandı: ${hex}` } },
      "-" as const,
      { label: "Arka planı sıfırla", onSelect: () => { $bg = "transparent"; $note = "Sıfırlandı" } },
    ]
  }
  return <div sx={{ flex: "col", gap: 2, p: 3, radius: 3 }} style={{ background: $bg }}>
    <ContextMenu items={items} label="Renk işlemleri">
      <div sx={{ flex: "row", gap: 2 }}>
        {colors.map(([name, hex]) => <Swatch color={hex} label={name} data-hex={hex} size="lg" shape="circle" selected={$bg === hex}
          onClick={() => { $bg = hex!; $note = `Arka plan: ${hex}` }} />)}
      </div>
    </ContextMenu>
    <span sx={{ text: "sm" }}>{$note}</span>
  </div>
}

import { ContextMenu } from "march/components/context-menu"

// sohbet: mesaja sağ tıkla (ya da odaklayıp Shift+F10); yalnız kendi mesajın silinebilir, boş alanda tarayıcı menüsü kalır
export function ChatMessages() {
  let $messages = [
    { id: 1, me: false, text: "Yarın toplantı 10'da mı?" },
    { id: 2, me: true, text: "Evet, 10'da. Sunumu ben getiriyorum." },
    { id: 3, me: false, text: "Harika, görüşürüz 👋" },
  ]
  let $pinned = ""
  const find = (t: Element) => $messages.find((m) => m.id === Number(t.closest("[data-id]")?.getAttribute("data-id")))
  return <div sx={{ flex: "col", gap: 2 }}>
    <span sx={{ text: "sm", color: "muted" }}>📌 {$pinned || "Sabitlenmiş mesaj yok"}</span>
    <ContextMenu label="Mesaj işlemleri" when={(t: Element) => !!t.closest("[data-id]")} items={(t: Element) => {
      const m = find(t)!
      return [
        { label: "Sabitle", onSelect: () => { $pinned = m.text } },
        { label: "Kopyala", shortcut: "mod+c" },
        "-",
        { label: "Sil", danger: true, disabled: !m.me, onSelect: () => { $messages = $messages.filter((x) => x.id !== m.id) } },
      ]
    }}>
      <div sx={{ flex: "col", gap: 1 }}>
        {$messages.map((m) => <p data-id={m.id} tabindex="0" sx={{ p: 2, radius: 3 }}
          style={{ alignSelf: m.me ? "flex-end" : "flex-start", margin: 0, background: m.me ? "var(--m-primary-soft)" : "var(--m-surface-2)" }}>{m.text}</p>)}
      </div>
    </ContextMenu>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { ContextMenuLab } from "./ContextMenuLab.tsx"

// ContextMenuLab'in testleri: kaydedince Testler sekmesinde çalışır
test("Menü tuşu odaklı öğede menüyü açar; öğe hedefi bilir", async () => {
  const s = renderTest(() => <ContextMenuLab />)
  await s.press("ContextMenu", s.get(".lab-on"))
  await s.flush(2)
  expect(s.sees("Hedefi yaz")).toBe(true)
  expect(s.get(".lab-menu")?.getAttribute("aria-label")).toBe("Lab menüsü")
  await s.click("Hedefi yaz")
  await s.flush(2)
  expect(s.get(".lab-last")?.textContent).toContain("hedef: Açılır")
})

test("when false döndürünce menü açılmaz", async () => {
  const s = renderTest(() => <ContextMenuLab />)
  await s.press("ContextMenu", s.get(".lab-off"))
  await s.flush(2)
  expect(s.sees("Hedefi yaz")).toBe(false)
  expect(s.get(".lab-area")).toBeTruthy()
})
